      ('Code',"// app.xuy\n// title: 计数器\nimport { signal, computed, mount } from 'xunay'\n\nconst n = signal(0)\nconst double = computed(() => n() * 2)\n\nmount(() => div({ class: 'app' },\n  h1(null, '计数器'),\n  div({ class: 'row' },\n    button({ on: { click: () => n(v => v - 1) } }, '-'),\n    span({ class: 'num' }, () => String(n())),\n    button({ on: { click: () => n(v => v + 1) } }, '+')\n  ),\n  p(null, () => '双倍: ' + double()),\n  button({ on: { click: () => n(0) } }, '重置')\n), '#app')",'xuy'),
