      ('H2','代码'),
      ('Code',"// app.xuy\nimport { signal, list, mount } from 'xunay'\n\nconst items = signal(Array.from({ length: 1000 }, (_, i) => ({\n  id: i + 1,\n  title: '项目 ' + (i + 1),\n  done: false\n})))\n\nconst pushFirst = () => items(l => [{ id: Date.now(), title: '新项目', done: false }, ...l])\nconst pushLast = () => items(l => [...l, { id: Date.now(), title: '新项目', done: false }])\nconst popFirst = () => items(l => l.slice(1))\nconst popLast = () => items(l => l.slice(0, -1))\nconst shuffle = () => items(l => [...l].sort(() => Math.random() - 0.5))\nconst toggleFirst = () => items(l => l.map((t, i) => i === 0 ? { ...t, done: !t.done } : t))\nconst clear = () => items([])\nconst reset = () => items(Array.from({ length: 1000 }, (_, i) => ({ id: i + 1, title: '项目 ' + (i + 1), done: false })))\n\nmount(() => div({ class: 'page' },\n  h1(null, '1000 行列表'),\n  p(null, () => '共 ' + items().length + ' 项'),\n\n  div({ class: 'row' },\n    button({ on: { click: pushFirst } }, '头部加'),\n    button({ on: { click: pushLast } }, '尾部加'),\n    button({ on: { click: popFirst } }, '头部删'),\n    button({ on: { click: popLast } }, '尾部删'),\n    button({ on: { click: shuffle } }, '打乱'),\n    button({ on: { click: toggleFirst } }, '切换第 1 项'),\n    button({ on: { click: clear } }, '清空'),\n    button({ on: { click: reset } }, '重置')\n  ),\n\n  ul({ class: 'list' },\n    list(items, t => t.id, t => li({ class: () => t.done ? 'done' : '' },\n      span(null, t.title)\n    ))\n  )\n), '#app')",'xuy'),
