      ('Code',"import { signal, list } from 'xunay'\n\nexport function App({ initialTodos = [] } = {}) {\n  const todos = signal(initialTodos)\n  return div({ class: 'app' },\n    h1(null, 'SSR 演示'),\n    p(null, () => '共 ' + todos().length + ' 条'),\n    ul(null, list(todos, t => t.id, t => li(null, t.title))),\n    button({ on: { click: () => todos(l => [...l, { id: Date.now(), title: '新任务' }]) } }, '添加')\n  )\n}",'xuy'),
      ('H2','服务端'),
      ('Code',"// server.js（需先 npm i express）\nimport express from 'express'\nimport { renderToString } from 'xunay/ssr'\nimport { App } from './App.js'\n\nconst app = express()\n\napp.get('/', async (req, res) => {\n  const todos = [\n    { id: 1, title: '学习 SSR' },\n    { id: 2, title: '看文档' }\n  ]\n  const html = renderToString(App({ initialTodos: todos }))\n  res.send(`\n    <!DOCTYPE html>\n    <html>\n    <head><title>SSR</title></head>\n    <body>\n      <div id=\"app\">${html}</div>\n      <script>window.__TODOS__ = ${JSON.stringify(todos)}</script>\n      <script type=\"module\" src=\"/client.js\"></script>\n    </body>\n    </html>\n  `)\n})\n\napp.listen(12340)",'js'),
